-- AWS-native billing and inventory ledger. No product, stock, invoice,
-- payment provider, or financial row is seeded. External card operations
-- remain fail-closed until a separately approved provider is registered.

create table clinical_core.billing_suppliers(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),name text not null,contact_email text,phone text,notes text,archived_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(id,organization_id));
create table clinical_core.billing_locations(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),name text not null,archived_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(id,organization_id));
create table clinical_core.billing_tax_rates(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),name text not null,rate_bps integer not null check(rate_bps between 0 and 10000),active boolean not null default true,created_at timestamptz not null default clock_timestamp(),unique(id,organization_id));
create table clinical_core.billing_products(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),catalog_product_stable_id text references clinical_reference.catalog_products(stable_id),name text not null,description text,kind text not null check(kind in('service','product','package','other')),sku text,barcode text,currency text not null default 'usd',amount_minor bigint not null check(amount_minor>=0),cost_minor bigint check(cost_minor is null or cost_minor>=0),supplier_id uuid references clinical_core.billing_suppliers(id),tax_rate_id uuid references clinical_core.billing_tax_rates(id),track_inventory boolean not null default false,reorder_threshold integer not null default 0 check(reorder_threshold>=0),version integer not null default 1,archived_at timestamptz,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(id,organization_id),unique(organization_id,sku));
create table clinical_core.inventory_stock(organization_id uuid not null references clinical_core.organizations(id),location_id uuid not null references clinical_core.billing_locations(id),product_id uuid not null references clinical_core.billing_products(id),on_hand integer not null default 0,reserved integer not null default 0,updated_at timestamptz not null default clock_timestamp(),primary key(location_id,product_id),check(on_hand>=0 and reserved>=0 and reserved<=on_hand));
create table clinical_core.inventory_ledger(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),location_id uuid not null references clinical_core.billing_locations(id),product_id uuid not null references clinical_core.billing_products(id),kind text not null,on_hand_delta integer not null,reserved_delta integer not null,reason_present boolean not null,reference text,unit_cost_minor bigint,supplier_id uuid references clinical_core.billing_suppliers(id),invoice_id uuid,actor_person_id uuid not null references clinical_core.persons(id),occurred_at timestamptz not null default clock_timestamp());
create table clinical_core.billing_invoices(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),patient_record_id uuid not null references clinical_core.patient_records(id),appointment_id uuid references clinical_core.appointments(id),location_id uuid references clinical_core.billing_locations(id),status text not null default 'draft' check(status in('draft','open','partially_paid','paid','void','partially_refunded','refunded')),version integer not null default 1,number text,currency text not null default 'usd',lines jsonb not null default '[]'::jsonb check(jsonb_typeof(lines)='array'),subtotal_minor bigint not null default 0,tax_minor bigint not null default 0,total_minor bigint not null default 0,credit_applied_minor bigint not null default 0,paid_minor bigint not null default 0,refunded_minor bigint not null default 0,inventory_reserved_at timestamptz,inventory_committed_at timestamptz,created_by_person_id uuid not null references clinical_core.persons(id),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(id,organization_id));
alter table clinical_core.inventory_ledger add constraint inventory_ledger_invoice_fk foreign key(invoice_id) references clinical_core.billing_invoices(id);
create table clinical_core.billing_payments(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),invoice_id uuid not null references clinical_core.billing_invoices(id),method text not null,status text not null check(status in('pending','succeeded','failed','refunded','partially_refunded')),amount_minor bigint not null check(amount_minor>0),idempotency_key text not null,reference text,provider_reference text,recorded_by_person_id uuid not null references clinical_core.persons(id),recorded_at timestamptz not null default clock_timestamp(),unique(organization_id,idempotency_key));
create table clinical_core.billing_refunds(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),payment_id uuid not null references clinical_core.billing_payments(id),amount_minor bigint not null check(amount_minor>0),method text not null,reason_present boolean not null,recorded_by_person_id uuid not null references clinical_core.persons(id),recorded_at timestamptz not null default clock_timestamp());
create table clinical_core.patient_credit_entries(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),patient_record_id uuid not null references clinical_core.patient_records(id),invoice_id uuid references clinical_core.billing_invoices(id),amount_minor bigint not null,reason_present boolean not null,actor_person_id uuid not null references clinical_core.persons(id),occurred_at timestamptz not null default clock_timestamp());
create table clinical_core.billing_provider_registrations(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),provider_key text not null,review_state text not null default 'pending_review' check(review_state in('pending_review','approved','rejected')),enabled boolean not null default false check(enabled=false),created_at timestamptz not null default clock_timestamp(),unique(organization_id,provider_key));
create table clinical_core.billing_events(id uuid primary key default public.gen_random_uuid(),organization_id uuid not null references clinical_core.organizations(id),invoice_id uuid references clinical_core.billing_invoices(id),action text not null,safe_metadata jsonb not null default '{}'::jsonb,actor_person_id uuid not null references clinical_core.persons(id),occurred_at timestamptz not null default clock_timestamp(),check(jsonb_typeof(safe_metadata)='object' and not(safe_metadata ?| array['reason','reference','email','phone','lines'])));

create index billing_products_org_idx on clinical_core.billing_products(organization_id,updated_at desc); create index inventory_ledger_product_idx on clinical_core.inventory_ledger(organization_id,product_id,occurred_at desc); create index billing_invoices_patient_idx on clinical_core.billing_invoices(organization_id,patient_record_id,created_at desc); create index billing_payments_invoice_idx on clinical_core.billing_payments(invoice_id,recorded_at desc); create index patient_credit_entries_patient_idx on clinical_core.patient_credit_entries(organization_id,patient_record_id,occurred_at desc);
do $$ declare _table text; begin foreach _table in array array['billing_suppliers','billing_locations','billing_tax_rates','billing_products','inventory_stock','inventory_ledger','billing_invoices','billing_payments','billing_refunds','patient_credit_entries','billing_provider_registrations','billing_events'] loop execute format('alter table clinical_core.%I enable row level security',_table); execute format('revoke all on clinical_core.%I from public,clinical_core_api',_table); end loop; end $$;
create trigger inventory_ledger_append_only before update or delete on clinical_core.inventory_ledger for each row execute function clinical_reference.reject_immutable_catalog_history();
create trigger billing_refunds_append_only before update or delete on clinical_core.billing_refunds for each row execute function clinical_reference.reject_immutable_catalog_history();
create trigger patient_credit_entries_append_only before update or delete on clinical_core.patient_credit_entries for each row execute function clinical_reference.reject_immutable_catalog_history();
create trigger billing_events_append_only before update or delete on clinical_core.billing_events for each row execute function clinical_reference.reject_immutable_catalog_history();

create or replace function clinical_private.billing_totals(_lines jsonb) returns jsonb language plpgsql immutable security definer set search_path='' as $$ declare _line jsonb; _subtotal bigint:=0; _tax bigint:=0; _qty integer; _amount bigint; _rate integer; begin if jsonb_typeof(_lines)<>'array' or jsonb_array_length(_lines)>100 then raise exception using errcode='22023',message='invoice_lines_invalid'; end if; for _line in select value from jsonb_array_elements(_lines) loop _qty:=coalesce((_line->>'quantity')::integer,0); _amount:=coalesce((_line->>'amountMinor')::bigint,-1); _rate:=coalesce((_line->>'taxRateBps')::integer,0); if _qty not between 1 and 1000 or _amount<0 or _rate not between 0 and 10000 or coalesce(_line->>'productId','')='' then raise exception using errcode='22023',message='invoice_line_invalid'; end if; _subtotal:=_subtotal+_qty*_amount; _tax:=_tax+round((_qty*_amount)*_rate/10000.0); end loop; return jsonb_build_object('subtotal',_subtotal,'tax',_tax,'total',_subtotal+_tax); end $$;

create or replace function clinical_core.invoke_billing_operation(_operation text,_args jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare _org uuid:=clinical_private.organization_id(); _actor uuid; _id uuid; _patient uuid; _invoice clinical_core.billing_invoices%rowtype; _product clinical_core.billing_products%rowtype; _payment clinical_core.billing_payments%rowtype; _version integer; _rows jsonb; _totals jsonb; _amount bigint; _balance bigint; _count integer; _line jsonb; _qty integer; _location uuid;
begin if _args is null or jsonb_typeof(_args)<>'object' or octet_length(_args::text)>524288 then raise exception using errcode='22023',message='billing_arguments_invalid'; end if; if (_args->>'_organization_id')::uuid<>_org then raise exception using errcode='42501',message='organization_context_mismatch'; end if; _actor:=clinical_private.require_knowledge_editor(_org);
  if _operation in('upsert_supplier','upsert_billing_location','upsert_tax_rate') then _id:=nullif(_args->>'_id','')::uuid;
    if _operation='upsert_supplier' then if _id is null then insert into clinical_core.billing_suppliers(organization_id,name,contact_email,phone,notes) values(_org,btrim(_args->>'_name'),nullif(_args->>'_contact_email',''),nullif(_args->>'_phone',''),nullif(_args->>'_notes','')) returning id into _id; else update clinical_core.billing_suppliers set name=btrim(_args->>'_name'),contact_email=nullif(_args->>'_contact_email',''),phone=nullif(_args->>'_phone',''),notes=nullif(_args->>'_notes',''),archived_at=case when (_args->>'_archive')::boolean then clock_timestamp() end where id=_id and organization_id=_org; end if;
    elsif _operation='upsert_billing_location' then if _id is null then insert into clinical_core.billing_locations(organization_id,name) values(_org,btrim(_args->>'_name')) returning id into _id; else update clinical_core.billing_locations set name=btrim(_args->>'_name'),archived_at=case when (_args->>'_archive')::boolean then clock_timestamp() end where id=_id and organization_id=_org; end if;
    else if _id is null then insert into clinical_core.billing_tax_rates(organization_id,name,rate_bps,active) values(_org,btrim(_args->>'_name'),(_args->>'_rate_bps')::integer,(_args->>'_active')::boolean) returning id into _id; else update clinical_core.billing_tax_rates set name=btrim(_args->>'_name'),rate_bps=(_args->>'_rate_bps')::integer,active=(_args->>'_active')::boolean where id=_id and organization_id=_org; end if; end if;
    if not found and _id is not null then raise exception using errcode='P0002',message='billing_reference_not_found'; end if; return jsonb_build_object('ok',true,'id',_id);
  elsif _operation='upsert_billing_product' then _id:=nullif(_args->>'_id','')::uuid;
    if _id is null then insert into clinical_core.billing_products(organization_id,catalog_product_stable_id,name,description,kind,sku,barcode,currency,amount_minor,cost_minor,supplier_id,tax_rate_id,track_inventory,reorder_threshold) values(_org,nullif(_args->>'_catalog_product_id',''),btrim(_args->>'_name'),nullif(_args->>'_description',''),_args->>'_kind',nullif(_args->>'_sku',''),nullif(_args->>'_barcode',''),lower(_args->>'_currency'),(_args->>'_amount_minor')::bigint,nullif(_args->>'_cost_minor','')::bigint,nullif(_args->>'_supplier_id','')::uuid,nullif(_args->>'_tax_rate_id','')::uuid,(_args->>'_track_inventory')::boolean,(_args->>'_reorder_threshold')::integer) returning id,version into _id,_version;
    else update clinical_core.billing_products set name=btrim(_args->>'_name'),description=nullif(_args->>'_description',''),kind=_args->>'_kind',sku=nullif(_args->>'_sku',''),barcode=nullif(_args->>'_barcode',''),currency=lower(_args->>'_currency'),amount_minor=(_args->>'_amount_minor')::bigint,cost_minor=nullif(_args->>'_cost_minor','')::bigint,supplier_id=nullif(_args->>'_supplier_id','')::uuid,tax_rate_id=nullif(_args->>'_tax_rate_id','')::uuid,track_inventory=(_args->>'_track_inventory')::boolean,reorder_threshold=(_args->>'_reorder_threshold')::integer,version=version+1,updated_at=clock_timestamp() where id=_id and organization_id=_org and version=(_args->>'_expected_version')::integer returning version into _version; if not found then raise exception using errcode='40001',message='billing_product_version_conflict'; end if; end if; return jsonb_build_object('ok',true,'productId',_id,'version',_version);
  elsif _operation='archive_billing_product' then _id:=(_args->>'_product_id')::uuid; update clinical_core.billing_products set archived_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() where id=_id and organization_id=_org and version=(_args->>'_expected_version')::integer returning version into _version; if not found then raise exception using errcode='40001',message='billing_product_version_conflict'; end if; return jsonb_build_object('ok',true,'productId',_id,'version',_version,'archived',true);
  elsif _operation in('receive_inventory_stock','adjust_inventory_stock') then _location:=(_args->>'_location_id')::uuid; _id:=(_args->>'_product_id')::uuid; select * into _product from clinical_core.billing_products where id=_id and organization_id=_org and track_inventory and archived_at is null; if not found then raise exception using errcode='P0002',message='tracked_product_not_found'; end if; _qty:=case when _operation='receive_inventory_stock' then (_args->>'_quantity')::integer else (_args->>'_delta')::integer end; insert into clinical_core.inventory_stock(organization_id,location_id,product_id,on_hand) values(_org,_location,_id,greatest(_qty,0)) on conflict(location_id,product_id) do update set on_hand=clinical_core.inventory_stock.on_hand+_qty,updated_at=clock_timestamp(); insert into clinical_core.inventory_ledger(organization_id,location_id,product_id,kind,on_hand_delta,reserved_delta,reason_present,reference,unit_cost_minor,supplier_id,actor_person_id) values(_org,_location,_id,case when _operation='receive_inventory_stock' then 'receipt' else _args->>'_kind' end,_qty,0,coalesce(_args->>'_reason','')<>'',nullif(_args->>'_reference',''),nullif(_args->>'_unit_cost_minor','')::bigint,nullif(_args->>'_supplier_id','')::uuid,_actor); return jsonb_build_object('ok',true,'productId',_id,'locationId',_location,'delta',_qty);
  elsif _operation='create_invoice_draft' then _patient:=(_args->>'_patient_id')::uuid; perform clinical_private.require_clinical_patient(_org,_patient); insert into clinical_core.billing_invoices(organization_id,patient_record_id,appointment_id,location_id,created_by_person_id) values(_org,_patient,nullif(_args->>'_appointment_id','')::uuid,nullif(_args->>'_location_id','')::uuid,_actor) returning id,version into _id,_version; return jsonb_build_object('ok',true,'invoiceId',_id,'version',_version,'status','draft');
  elsif _operation in('save_invoice_draft','finalize_invoice','void_invoice','apply_patient_credit','start_card_payment') then _id:=(_args->>'_invoice_id')::uuid; select * into _invoice from clinical_core.billing_invoices where id=_id and organization_id=_org for update; if not found then raise exception using errcode='P0002',message='invoice_not_found'; end if; perform clinical_private.require_clinical_patient(_org,_invoice.patient_record_id); if _invoice.version<>(_args->>'_expected_version')::integer then raise exception using errcode='40001',message='invoice_version_conflict'; end if;
    if _operation='save_invoice_draft' then if _invoice.status<>'draft' then raise exception using errcode='55000',message='invoice_not_editable'; end if; _totals:=clinical_private.billing_totals(_args->'_lines'); update clinical_core.billing_invoices set lines=_args->'_lines',location_id=nullif(_args->>'_location_id','')::uuid,subtotal_minor=(_totals->>'subtotal')::bigint,tax_minor=(_totals->>'tax')::bigint,total_minor=(_totals->>'total')::bigint,version=version+1,updated_at=clock_timestamp() where id=_id returning version into _version; return jsonb_build_object('ok',true,'invoiceId',_id,'version',_version,'totals',_totals);
    elsif _operation='finalize_invoice' then if _invoice.status<>'draft' or jsonb_array_length(_invoice.lines)=0 then raise exception using errcode='55000',message='invoice_not_finalizable'; end if; for _line in select value from jsonb_array_elements(_invoice.lines) loop _qty:=(_line->>'quantity')::integer; select * into _product from clinical_core.billing_products where id=(_line->>'productId')::uuid and organization_id=_org; if _product.track_inventory then _location:=coalesce((_line->>'locationId')::uuid,_invoice.location_id); update clinical_core.inventory_stock set reserved=reserved+_qty,updated_at=clock_timestamp() where location_id=_location and product_id=_product.id and on_hand-reserved>=_qty; if not found then raise exception using errcode='40001',message='insufficient_inventory'; end if; insert into clinical_core.inventory_ledger(organization_id,location_id,product_id,kind,on_hand_delta,reserved_delta,reason_present,invoice_id,actor_person_id) values(_org,_location,_product.id,'reserve',0,_qty,false,_id,_actor); end if; end loop; update clinical_core.billing_invoices set status='open',number='INV-'||upper(substr(replace(id::text,'-',''),1,12)),inventory_reserved_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() where id=_id returning version into _version; return jsonb_build_object('ok',true,'invoiceId',_id,'version',_version,'status','open');
    elsif _operation='void_invoice' then if _invoice.status not in('draft','open') then raise exception using errcode='55000',message='invoice_not_voidable'; end if; if _invoice.inventory_reserved_at is not null and _invoice.inventory_committed_at is null then for _line in select value from jsonb_array_elements(_invoice.lines) loop _qty:=(_line->>'quantity')::integer; _location:=coalesce((_line->>'locationId')::uuid,_invoice.location_id); update clinical_core.inventory_stock set reserved=reserved-_qty where location_id=_location and product_id=(_line->>'productId')::uuid and reserved>=_qty; end loop; end if; update clinical_core.billing_invoices set status='void',version=version+1,updated_at=clock_timestamp() where id=_id returning version into _version; return jsonb_build_object('ok',true,'invoiceId',_id,'version',_version,'status','void');
    elsif _operation='apply_patient_credit' then _amount:=(_args->>'_amount_minor')::bigint; _balance:=(select coalesce(sum(amount_minor),0) from clinical_core.patient_credit_entries where organization_id=_org and patient_record_id=_invoice.patient_record_id); if _amount<=0 or _amount>_balance or _amount>_invoice.total_minor-_invoice.paid_minor-_invoice.credit_applied_minor then raise exception using errcode='22023',message='patient_credit_invalid'; end if; insert into clinical_core.patient_credit_entries(organization_id,patient_record_id,invoice_id,amount_minor,reason_present,actor_person_id) values(_org,_invoice.patient_record_id,_id,-_amount,false,_actor); update clinical_core.billing_invoices set credit_applied_minor=credit_applied_minor+_amount,version=version+1,updated_at=clock_timestamp() where id=_id returning version into _version; return jsonb_build_object('ok',true,'invoiceId',_id,'version',_version,'creditAppliedMinor',_amount);
    else if not exists(select 1 from clinical_core.billing_provider_registrations where organization_id=_org and provider_key='card' and review_state='approved' and enabled) then raise exception using errcode='55000',message='card_payment_provider_not_approved'; end if; raise exception using errcode='55000',message='card_payment_delivery_disabled'; end if;
  elsif _operation='record_manual_payment' then _id:=(_args->>'_invoice_id')::uuid; select * into _invoice from clinical_core.billing_invoices where id=_id and organization_id=_org for update; if not found or _invoice.version<>(_args->>'_expected_version')::integer or _invoice.status not in('open','partially_paid') then raise exception using errcode='40001',message='invoice_payment_conflict'; end if; _amount:=(_args->>'_amount_minor')::bigint; if _amount<=0 or _amount>_invoice.total_minor-_invoice.credit_applied_minor-_invoice.paid_minor then raise exception using errcode='22023',message='payment_amount_invalid'; end if; insert into clinical_core.billing_payments(organization_id,invoice_id,method,status,amount_minor,idempotency_key,reference,recorded_by_person_id) values(_org,_id,_args->>'_method','succeeded',_amount,_args->>'_idempotency_key',nullif(_args->>'_reference',''),_actor) on conflict(organization_id,idempotency_key) do nothing returning id into _id; if _id is null then select id into _id from clinical_core.billing_payments where organization_id=_org and idempotency_key=_args->>'_idempotency_key'; end if; update clinical_core.billing_invoices set paid_minor=paid_minor+_amount,status=case when paid_minor+_amount+credit_applied_minor>=total_minor then 'paid' else 'partially_paid' end,version=version+1,updated_at=clock_timestamp() where id=_invoice.id returning version,status into _version,_invoice.status; if _invoice.status='paid' and _invoice.inventory_reserved_at is not null and _invoice.inventory_committed_at is null then for _line in select value from jsonb_array_elements(_invoice.lines) loop _qty:=(_line->>'quantity')::integer; _location:=coalesce((_line->>'locationId')::uuid,_invoice.location_id); update clinical_core.inventory_stock set on_hand=on_hand-_qty,reserved=reserved-_qty where location_id=_location and product_id=(_line->>'productId')::uuid; end loop; update clinical_core.billing_invoices set inventory_committed_at=clock_timestamp() where id=_invoice.id; end if; return jsonb_build_object('ok',true,'paymentId',_id,'invoiceId',_invoice.id,'version',_version,'status',_invoice.status);
  elsif _operation='refund_payment' then _id:=(_args->>'_payment_id')::uuid; select * into _payment from clinical_core.billing_payments where id=_id and organization_id=_org for update; if not found or _payment.status not in('succeeded','partially_refunded') then raise exception using errcode='P0002',message='payment_not_refundable'; end if; _amount:=(_args->>'_amount_minor')::bigint; _balance:=_payment.amount_minor-(select coalesce(sum(amount_minor),0) from clinical_core.billing_refunds where payment_id=_id); if _amount<=0 or _amount>_balance then raise exception using errcode='22023',message='refund_amount_invalid'; end if; insert into clinical_core.billing_refunds(organization_id,payment_id,amount_minor,method,reason_present,recorded_by_person_id) values(_org,_id,_amount,_args->>'_method',true,_actor) returning id into _id; update clinical_core.billing_payments set status=case when _amount=_balance then 'refunded' else 'partially_refunded' end where id=_payment.id; update clinical_core.billing_invoices set refunded_minor=refunded_minor+_amount,status=case when refunded_minor+_amount>=paid_minor then 'refunded' else 'partially_refunded' end,version=version+1 where id=_payment.invoice_id; return jsonb_build_object('ok',true,'refundId',_id,'paymentId',_payment.id,'inventoryRestocked',false);
  elsif _operation='grant_patient_credit' then _patient:=(_args->>'_patient_id')::uuid; perform clinical_private.require_clinical_patient(_org,_patient); _amount:=(_args->>'_amount_minor')::bigint; if _amount<=0 then raise exception using errcode='22023',message='credit_amount_invalid'; end if; insert into clinical_core.patient_credit_entries(organization_id,patient_record_id,amount_minor,reason_present,actor_person_id) values(_org,_patient,_amount,true,_actor) returning id into _id; return jsonb_build_object('ok',true,'creditEntryId',_id,'amountMinor',_amount);
  elsif _operation='return_inventory_stock' then _location:=(_args->>'_location_id')::uuid; _id:=(_args->>'_product_id')::uuid; _qty:=(_args->>'_quantity')::integer; if _qty<=0 or coalesce(btrim(_args->>'_condition'),'')='' or coalesce(btrim(_args->>'_reason'),'')='' then raise exception using errcode='22023',message='inventory_return_invalid'; end if; insert into clinical_core.inventory_stock(organization_id,location_id,product_id,on_hand) values(_org,_location,_id,_qty) on conflict(location_id,product_id) do update set on_hand=clinical_core.inventory_stock.on_hand+_qty; insert into clinical_core.inventory_ledger(organization_id,location_id,product_id,kind,on_hand_delta,reserved_delta,reason_present,invoice_id,actor_person_id) values(_org,_location,_id,'return',_qty,0,true,(_args->>'_invoice_id')::uuid,_actor); return jsonb_build_object('ok',true,'productId',_id,'quantity',_qty);
  elsif _operation='get_billing_invoice' then _id:=(_args->>'_invoice_id')::uuid; select jsonb_build_object('id',i.id,'patientId',i.patient_record_id,'status',i.status,'version',i.version,'number',i.number,'currency',i.currency,'lines',i.lines,'subtotalMinor',i.subtotal_minor,'taxMinor',i.tax_minor,'totalMinor',i.total_minor,'creditAppliedMinor',i.credit_applied_minor,'paidMinor',i.paid_minor,'refundedMinor',i.refunded_minor,'payments',coalesce((select jsonb_agg(to_jsonb(p) order by p.recorded_at) from clinical_core.billing_payments p where p.invoice_id=i.id),'[]'::jsonb)) into _rows from clinical_core.billing_invoices i where i.id=_id and i.organization_id=_org; if _rows is null then raise exception using errcode='P0002',message='invoice_not_found'; end if; return _rows;
  elsif _operation='get_patient_billing' then _patient:=(_args->>'_patient_id')::uuid; perform clinical_private.require_clinical_patient(_org,_patient); return jsonb_build_object('patientId',_patient,'creditBalanceMinor',(select coalesce(sum(amount_minor),0) from clinical_core.patient_credit_entries where organization_id=_org and patient_record_id=_patient),'invoices',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'number',i.number,'status',i.status,'totalMinor',i.total_minor,'paidMinor',i.paid_minor,'createdAt',i.created_at) order by i.created_at desc) from clinical_core.billing_invoices i where i.organization_id=_org and i.patient_record_id=_patient),'[]'::jsonb));
  elsif _operation='get_inventory_history' then select coalesce(jsonb_agg(to_jsonb(l) order by l.occurred_at desc),'[]'::jsonb) into _rows from (select * from clinical_core.inventory_ledger where organization_id=_org and product_id=(_args->>'_product_id')::uuid and location_id=(_args->>'_location_id')::uuid order by occurred_at desc limit least(greatest((_args->>'_limit')::integer,1),200))l; return jsonb_build_object('entries',_rows);
  elsif _operation='list_billing_catalog' then select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'kind',p.kind,'sku',p.sku,'currency',p.currency,'amountMinor',p.amount_minor,'trackInventory',p.track_inventory,'reorderThreshold',p.reorder_threshold,'version',p.version,'archived',p.archived_at is not null,'stock',coalesce((select jsonb_agg(jsonb_build_object('locationId',s.location_id,'onHand',s.on_hand,'reserved',s.reserved)) from clinical_core.inventory_stock s where s.product_id=p.id),'[]'::jsonb)) order by p.name),'[]'::jsonb) into _rows from clinical_core.billing_products p where p.organization_id=_org and ((_args->>'_include_archived')::boolean or p.archived_at is null) and (nullif(_args->>'_kind','') is null or p.kind=_args->>'_kind') and (nullif(_args->>'_query','') is null or p.name ilike '%'||(_args->>'_query')||'%') limit least(greatest((_args->>'_limit')::integer,1),200); return jsonb_build_object('products',_rows);
  elsif _operation='get_billing_workspace' then return jsonb_build_object('invoices',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'patientId',i.patient_record_id,'number',i.number,'status',i.status,'totalMinor',i.total_minor,'paidMinor',i.paid_minor,'createdAt',i.created_at) order by i.created_at desc) from clinical_core.billing_invoices i where i.organization_id=_org and (nullif(_args->>'_status','') is null or i.status=_args->>'_status')),'[]'::jsonb),'generatedAt',clock_timestamp());
  else raise exception using errcode='0A000',message='billing_operation_refused'; end if;
end $$;
revoke all on function clinical_private.billing_totals(jsonb) from public; revoke all on function clinical_core.invoke_billing_operation(text,jsonb) from public; grant execute on function clinical_core.invoke_billing_operation(text,jsonb) to clinical_core_api;
